css:
.p14-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p14-page > .deck, .p14-page > .p14-center { grid-row: 2; align-self: center; }
.p14-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p14-top:empty { display: none; }
.p14-strip { --p14-strip-h: 9.5rem; }
.p14-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p14-strip-h)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p14-strip { --p14-strip-h: 19.5rem; } }
@media (max-width: 21.25rem) { .p14-strip { --p14-strip-h: 29.5rem; } }
.p14-scrolled .p14-page { margin-top: -5.25rem; }
.p14-e { --frame-w: var(--w2); }
.p14-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p14-w { position: relative; display: inline-grid; }
.p14-tipw { position: relative; display: inline-flex; }
.p14-tip-up { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); left: 50%; translate: -50% 0; width: max-content; max-width: min(17.5rem, 80vw); text-align: center; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p14-tip-up.p14-tip-start { left: 0; translate: 0 0; text-align: start; }
  .p14-tip-up.p14-tip-end { left: auto; right: 0; translate: 0 0; text-align: end; }
}
.p14-tip-dn { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p14-tip-ask { position: absolute; z-index: 30; top: 100%; left: 0; width: max-content; max-width: min(17.5rem, 70vw); }

.deck-card__foot.p-solo > :first-child { justify-self: center; }
.p-state { display: flex; align-items: center; min-height: 1.5rem; margin-top: calc(var(--s-1) * -1); }
.p-ask { display: inline-grid; place-items: center; min-width: var(--hit); min-height: var(--hit); margin-inline-start: calc(var(--s-2) * -1); padding: 0; border: var(--w1) solid transparent; border-radius: var(--r); background: transparent; color: var(--ink); cursor: pointer; }
.p-dashring { width: 0.625rem; height: 0.625rem; border: 1.5px dashed var(--muted); border-radius: 50%; }
.p-state--ask { position: relative; }

.p14-face { gap: var(--s-3); }
.p14-win .deck-card__head { margin-top: 0; }
.p14-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; gap: var(--s-4); align-content: start; font-size: var(--fs-small); line-height: var(--lh-small); padding-block: var(--s-1); border-bottom: var(--w1) solid var(--rule); }
.p14-foot { flex: none; display: flex; gap: var(--s-2); justify-content: space-between; }
.p14-foot > * { flex: 1 1 0; }
.p14-foot--one { justify-content: center; }
.p14-foot--one > * { flex: 0 1 auto; min-width: 9rem; }

.p14-body { gap: var(--s-3); padding-block: var(--s-1); }
.p14-fh { justify-content: flex-start; flex-wrap: wrap; column-gap: var(--s-2); }
.p14-name { min-height: var(--ctl-h); resize: none; field-sizing: content; padding-block: calc((var(--ctl-h) - var(--lh-body)) / 2 - var(--w1)); }
.p14-pair { display: grid; gap: var(--s-1); }   
.p14-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-2); align-items: start; }
@container card (max-width: 18rem) { .p14-two { grid-template-columns: minmax(0, 1fr); } }
.p14-sel-ph { color: var(--muted); }
.p14-list { max-height: 11rem; overflow: auto; min-width: 0; display: flex; flex-direction: column; }
.p14-list > * { flex: none; }
.p14-list .menu__item { align-items: flex-start; flex-direction: column; gap: 0; justify-content: center; min-height: var(--row-h); padding-block: var(--s-1); }
.p14-list .menu__item > .row { width: 100%; justify-content: space-between; }
.p14-opt-sub { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); font-weight: var(--fw-regular); }
.p14-list .menu__item[aria-selected="true"] .p14-opt-sub { color: var(--blue); }
.p14-list .menu__item[aria-disabled="true"] .p14-opt-sub { color: var(--c-disabled-text); }
.p14-opt-done { color: var(--muted); }
.p14-group { padding: var(--s-1) var(--s-3) 0; font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-bold); color: var(--muted); }
.p14-sh { display: contents; }
.p14-shw { display: grid; gap: var(--s-3); }
.p14-hintc { }
.p14-notice { }
.p14-transfer { display: grid; gap: var(--s-2); padding-top: var(--s-3); border-top: var(--w1) solid var(--rule); }
.p14-transfer .row { align-items: flex-start; }
.p14-transfer .p14-grow { flex: 1; min-width: 0; }

.select.p14-off { border-color: var(--c-disabled-border); color: var(--c-disabled-text); cursor: not-allowed; }
.p14-ufoot { flex-direction: column; }
.p14-ufoot > * { flex: none; }
.p14-foot .p14-tipw { flex: 1 1 0; display: flex; }
.p14-foot .p14-tipw > .btn { flex: 1; }
.p14-foot .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p14-dlg .dialog__body p { max-width: var(--measure); }
.p14-stop { justify-self: start; }
.p14-check-wrap { display: grid; gap: var(--s-1); }
.p14-deleted { display: grid; align-content: center; min-height: 100%; }
.p14-foot--one { justify-content: center; }
.p14-foot--one > * { flex: 0 1 auto; min-width: 9rem; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p14-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p14-win) ~ .deck__controls { display: none; }
.p14-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p14-win-off, 0rem)); display: flex; flex-direction: column; }
.p14-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p14-win [class*="-body"], .p14-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p14-strip { --p14-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p14-strip { --p14-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p14-strip { --p14-win-off: 29.5rem; } }
.p14-strip.p14-strip--b { --p14-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p14-strip.p14-strip--b { --p14-win-off: 8rem; } }

.p14-body { scroll-snap-type: y mandatory; }
.p14-at { scroll-snap-align: start; }

.p14-foot:has(.p14-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p14-foot .p14-tipw { display: contents; }
.p14-foot .p14-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }
.p14-draft { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
